function importPatchFor(existing:V,row:V){const patch:Partial<V>={};for(const key of importUpdatableFields){const nuevo=(row as any)[key];const actual=(existing as any)[key];const nn=nuevo??null,aa=actual??null;if((key==="installer_id"||key==="installer_name")&&nn===null)continue;/* no desasignar por celda vacía */ if(typeof nn==="number"||typeof aa==="number"){if(Number(nn||0)!==Number(aa||0))(patch as any)[key]=nn}else if(typeof nn==="boolean"||typeof aa==="boolean"){if(Boolean(nn)!==Boolean(aa))(patch as any)[key]=nn}else if(String(nn??"").trim()!==String(aa??"").trim()){if(String(nn??"").trim()==="")continue;/* celda vacía no borra datos */(patch as any)[key]=nn}}return patch}
